code='''def transform(grid):
    """Recolor complete separator lines from 6/3 to 2; leave scattered marks unchanged."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row}
    for color in colors:
        rows = [r for r in range(h) if all(grid[r][c] == color for c in range(w))]
        cols = [c for c in range(w) if all(grid[r][c] == color for r in range(h))]
        for r in rows:
            for c in range(w):
                out[r][c] = 2
        for c in cols:
            for r in range(h):
                out[r][c] = 2
    return out
'''
